def transform(grid):
    """Restore color-2 occlusions using the grid's dihedral symmetries."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                # The background pattern has 180-degree rotational symmetry;
                # missing patches are copied from their opposite position.
                orbit = [(h - 1 - r, w - 1 - c)]
                # Include the reflection-equivalent position only as fallback.
                orbit.extend(((r, w - 1 - c), (h - 1 - r, c)))
                known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
                if known:
                    out[r][c] = max(set(known), key=known.count)
    return out
